import{_ as p,a0 as l,w as d,s as r,ao as o,I as n,x as e,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"网络地址转换（NAT）之报文跟踪 | LCTT x X-CMD","titleTemplate":false,"description":"网络地址转换（NAT）之报文跟踪 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"网络地址转换（NAT）之报文跟踪 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"网络地址转换（NAT）之报文跟踪 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210104 Network address translation part 1 - packet tracing","title":"网络地址转换（NAT）之报文跟踪","tag":"202105","desc":""},"relativePath":"202105/20210104 Network address translation part 1 - packet tracing.md","filePath":"[post].md"}'),c={name:"202105/20210104 Network address translation part 1 - packet tracing.md"};function h(g,a,u,k,b,f){const s=l("Link");return d(),r("div",null,[a[15]||(a[15]=o(`<h1 id="网络地址转换-nat-之报文跟踪" tabindex="-1">网络地址转换（NAT）之报文跟踪 <a class="header-anchor" href="#网络地址转换-nat-之报文跟踪" aria-label="Permalink to “网络地址转换（NAT）之报文跟踪”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202105/06/112410xhdkvvdajis3jhlj.jpg" alt=""></p><p>这是有关<ruby>网络地址转换<rt>network address translation</rt></ruby>（NAT）的系列文章中的第一篇。这一部分将展示如何使用 iptables/nftables 报文跟踪功能来定位 NAT 相关的连接问题。</p><h3 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h3><p>网络地址转换（NAT）是一种将容器或虚拟机暴露在互联网中的一种方式。传入的连接请求将其目标地址改写为另一个地址，随后被路由到容器或虚拟机。相同的技术也可用于负载均衡，即传入的连接被分散到不同的服务器上去。</p><p>当网络地址转换没有按预期工作时，连接请求将失败，会暴露错误的服务，连接最终出现在错误的容器中，或者请求超时，等等。调试此类问题的一种方法是检查传入请求是否与预期或已配置的转换相匹配。</p><h3 id="连接跟踪" tabindex="-1">连接跟踪 <a class="header-anchor" href="#连接跟踪" aria-label="Permalink to “连接跟踪”">​</a></h3><p>NAT 不仅仅是修改 IP 地址或端口号。例如，在将地址 X 映射到 Y 时，无需添加新规则来执行反向转换。一个被称为 “conntrack” 的 netfilter 系统可以识别已有连接的回复报文。每个连接都在 conntrack 系统中有自己的 NAT 状态。反向转换是自动完成的。</p><h3 id="规则匹配跟踪" tabindex="-1">规则匹配跟踪 <a class="header-anchor" href="#规则匹配跟踪" aria-label="Permalink to “规则匹配跟踪”">​</a></h3><p>nftables 工具（以及在较小的程度上，iptables）允许针对某个报文检查其处理方式以及该报文匹配规则集合中的哪条规则。为了使用这项特殊的功能，可在合适的位置插入“跟踪规则”。这些规则会选择被跟踪的报文。假设一个来自 IP 地址 C 的主机正在访问一个 IP 地址是 S 以及端口是 P 的服务。我们想知道报文匹配了哪条 NAT 转换规则，系统检查了哪些规则，以及报文是否在哪里被丢弃了。</p><p>由于我们要处理的是传入连接，所以我们将规则添加到 prerouting 钩子上。prerouting 意味着内核尚未决定将报文发往何处。修改目标地址通常会使报文被系统转发，而不是由主机自身处理。</p><h3 id="初始配置" tabindex="-1">初始配置 <a class="header-anchor" href="#初始配置" aria-label="Permalink to “初始配置”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft &#39;add table inet trace_debug&#39;</span></span>
<span class="line"><span># nft &#39;add chain inet trace_debug trace_pre { type filter hook prerouting priority -200000; }&#39;</span></span>
<span class="line"><span># nft &quot;insert rule inet trace_debug trace_pre ip saddr $C ip daddr $S tcp dport $P tcp flags syn limit rate 1/second meta nftrace set 1&quot;</span></span></code></pre></div><p>第一条规则添加了一张新的规则表，这使得将来删除和调试规则可以更轻松。一句 <code>nft delete table inet trace_debug</code> 命令就可以删除调试期间临时加入表中的所有规则和链。</p><p>第二条规则在系统进行路由选择之前（<code>prerouting</code> 钩子）创建了一个基本钩子，并将其优先级设置为负数，以保证它在连接跟踪流程和 NAT 规则匹配之前被执行。</p><p>然而，唯一最重要的部分是第三条规则的最后一段：<code>meta nftrace set 1</code>。这条规则会使系统记录所有匹配这条规则的报文所关联的事件。为了尽可能高效地查看跟踪信息（提高信噪比），考虑对跟踪的事件增加一个速率限制，以保证其数量处于可管理的范围。一个好的选择是限制每秒钟最多一个报文或一分钟最多一个报文。上述案例记录了所有来自终端 <code>$C</code> 且去往终端 <code>$S</code> 的端口 <code>$P</code> 的所有 SYN 报文和 SYN/ACK 报文。限制速率的配置语句可以防范事件过多导致的洪泛风险。事实上，大多数情况下只记录一个报文就足够了。</p><p>对于 iptables 用户来讲，配置流程是类似的。等价的配置规则类似于：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># iptables -t raw -I PREROUTING -s $C -d $S -p tcp --tcp-flags SYN SYN  --dport $P  -m limit --limit 1/s -j TRACE</span></span></code></pre></div><h3 id="获取跟踪事件" tabindex="-1">获取跟踪事件 <a class="header-anchor" href="#获取跟踪事件" aria-label="Permalink to “获取跟踪事件”">​</a></h3><p>原生 nft 工具的用户可以直接运行 <code>nft</code> 进入 nft 跟踪模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft monitor trace</span></span></code></pre></div><p>这条命令会将收到的报文以及所有匹配该报文的规则打印出来（用 <code>CTRL-C</code> 来停止输出）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id f0f627 ip raw prerouting  packet: iif &quot;veth0&quot; ether saddr ..</span></span></code></pre></div><p>我们将在下一章详细分析该结果。如果你用的是 iptables，首先通过 <code>iptables –version</code> 命令检查一下已安装的版本。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span># iptables --version</span></span>
<span class="line"><span>iptables v1.8.5 (legacy)</span></span></code></pre></div><p><code>(legacy)</code> 意味着被跟踪的事件会被记录到内核的环形缓冲区中。你可以用 <code>dmesg</code> 或 <code>journalctl</code> 命令来查看这些事件。这些调试输出缺少一些信息，但和新工具提供的输出从概念上来讲很类似。你将需要首先查看规则被记录下来的行号，并与活跃的 iptables 规则集合手动关联。如果输出显示 <code>(nf_tables)</code>，你可以使用 <code>xtables-monitor</code> 工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># xtables-monitor --trace</span></span></code></pre></div><p>如果上述命令仅显示版本号，你仍然需要查看 <code>dmesg</code>/<code>journalctl</code> 的输出。<code>xtables-monitor</code> 工具和 <code>nft</code> 监控跟踪工具使用相同的内核接口。它们之间唯一的不同点就是，<code>xtables-monitor</code> 工具会用 <code>iptables</code> 的语法打印事件，且如果你同时使用了 <code>iptables-nft</code> 和 <code>nft</code>，它将不能打印那些使用了 maps/sets 或其他只有 nftables 才支持的功能的规则。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h3><p>我们假设需要调试一个到虚拟机/容器的端口不通的问题。<code>ssh -p 1222 10.1.2.3</code> 命令应该可以远程连接那台服务器上的某个容器，但连接请求超时了。</p><p>你拥有运行那台容器的主机的登录权限。现在登录该机器并增加一条跟踪规则。可通过前述案例查看如何增加一个临时的调试规则表。跟踪规则类似于这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft &quot;insert rule inet trace_debug trace_pre ip daddr 10.1.2.3 tcp dport 1222 tcp flags syn limit rate 6/minute meta nftrace set 1&quot;</span></span></code></pre></div><p>在添加完上述规则后，运行 <code>nft monitor trace</code>，在跟踪模式下启动 nft，然后重试刚才失败的 <code>ssh</code> 命令。如果规则集较大，会出现大量的输出。不用担心这些输出，下一节我们会做逐行分析。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre packet: iif &quot;enp0&quot; ether saddr .. ip saddr 10.2.1.2 ip daddr 10.1.2.3 ip protocol tcp tcp dport 1222 tcp flags == syn</span></span>
<span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre rule ip daddr 10.2.1.2 tcp dport 1222 tcp flags syn limit rate 6/minute meta nftrace set 1 (verdict continue)</span></span>
<span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre verdict continue</span></span>
<span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre policy accept</span></span>
<span class="line"><span>trace id 9c01f8 inet nat prerouting packet: iif &quot;enp0&quot; ether saddr .. ip saddr 10.2.1.2 ip daddr 10.1.2.3 ip protocol tcp  tcp dport 1222 tcp flags == syn</span></span>
<span class="line"><span>trace id 9c01f8 inet nat prerouting rule ip daddr 10.1.2.3  tcp dport 1222 dnat ip to 192.168.70.10:22 (verdict accept)</span></span>
<span class="line"><span>trace id 9c01f8 inet filter forward packet: iif &quot;enp0&quot; oif &quot;veth21&quot; ether saddr .. ip daddr 192.168.70.10 .. tcp dport 22 tcp flags == syn tcp window 29200</span></span>
<span class="line"><span>trace id 9c01f8 inet filter forward rule ct status dnat jump allowed_dnats (verdict jump allowed_dnats)</span></span>
<span class="line"><span>trace id 9c01f8 inet filter allowed_dnats rule drop (verdict drop)</span></span>
<span class="line"><span>trace id 20a4ef inet trace_debug trace_pre packet: iif &quot;enp0&quot; ether saddr .. ip saddr 10.2.1.2 ip daddr 10.1.2.3 ip protocol tcp tcp dport 1222 tcp flags == syn</span></span></code></pre></div><h3 id="对跟踪结果作逐行分析" tabindex="-1">对跟踪结果作逐行分析 <a class="header-anchor" href="#对跟踪结果作逐行分析" aria-label="Permalink to “对跟踪结果作逐行分析”">​</a></h3><p>输出结果的第一行是触发后续输出的报文编号。这一行的语法与 nft 规则语法相同，同时还包括了接收报文的首部字段信息。你也可以在这一行找到接收报文的接口名称（此处为 <code>enp0</code>）、报文的源和目的 MAC 地址、报文的源 IP 地址（可能很重要 - 报告问题的人可能选择了一个错误的或非预期的主机），以及 TCP 的源和目的端口。同时你也可以在这一行的开头看到一个“跟踪编号”。该编号标识了匹配跟踪规则的特定报文。第二行包括了该报文匹配的第一条跟踪规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre rule ip daddr 10.2.1.2 tcp dport 1222 tcp flags syn limit rate 6/minute meta nftrace set 1 (verdict continue)</span></span></code></pre></div><p>这就是刚添加的跟踪规则。这里显示的第一条规则总是激活报文跟踪的规则。如果在这之前还有其他规则，它们将不会在这里显示。如果没有任何跟踪输出结果，说明没有抵达这条跟踪规则，或者没有匹配成功。下面的两行表明没有后续的匹配规则，且 <code>trace_pre</code> 钩子允许报文继续传输（判定为接受）。</p><p>下一条匹配规则是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet nat prerouting rule ip daddr 10.1.2.3  tcp dport 1222 dnat ip to 192.168.70.10:22 (verdict accept)</span></span></code></pre></div><p>这条 DNAT 规则设置了一个到其他地址和端口的映射。规则中的参数 <code>192.168.70.10</code> 是需要收包的虚拟机的地址，目前为止没有问题。如果它不是正确的虚拟机地址，说明地址输入错误，或者匹配了错误的 NAT 规则。</p><h3 id="ip-转发" tabindex="-1">IP 转发 <a class="header-anchor" href="#ip-转发" aria-label="Permalink to “IP 转发”">​</a></h3><p>通过下面的输出我们可以看到，IP 路由引擎告诉 IP 协议栈，该报文需要被转发到另一个主机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet filter forward packet: iif &quot;enp0&quot; oif &quot;veth21&quot; ether saddr .. ip daddr 192.168.70.10 .. tcp dport 22 tcp flags == syn tcp window 29200</span></span></code></pre></div><p>这是接收到的报文的另一种呈现形式，但和之前相比有一些有趣的不同。现在的结果有了一个输出接口集合。这在之前不存在的，因为之前的规则是在路由决策之前（<code>prerouting</code> 钩子）。跟踪编号和之前一样，因此仍然是相同的报文，但目标地址和端口已经被修改。假设现在还有匹配 <code>tcp dport 1222</code> 的规则，它们将不会对现阶段的报文产生任何影响了。</p><p>如果该行不包含输出接口（<code>oif</code>），说明路由决策将报文路由到了本机。对路由过程的调试属于另外一个主题，本文不再涉及。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet filter forward rule ct status dnat jump allowed_dnats (verdict jump allowed_dnats)</span></span></code></pre></div><p>这条输出表明，报文匹配到了一个跳转到 <code>allowed_dnats</code> 链的规则。下一行则说明了连接失败的根本原因：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet filter allowed_dnats rule drop (verdict drop)</span></span></code></pre></div><p>这条规则无条件地将报文丢弃，因此后续没有关于该报文的日志输出。下一行则是另一个报文的输出结果了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 20a4ef inet trace_debug trace_pre packet: iif &quot;enp0&quot; ether saddr .. ip saddr 10.2.1.2 ip daddr 10.1.2.3 ip protocol tcp tcp dport 1222 tcp flags == syn</span></span></code></pre></div><p>跟踪编号已经和之前不一样，然后报文的内容却和之前是一样的。这是一个重传尝试：第一个报文被丢弃了，因此 TCP 尝试了重传。可以忽略掉剩余的输出结果了，因为它并没有提供新的信息。现在是时候检查那条链了。</p><h3 id="规则集合分析" tabindex="-1">规则集合分析 <a class="header-anchor" href="#规则集合分析" aria-label="Permalink to “规则集合分析”">​</a></h3><p>上一节我们发现报文在 inet filter 表中的一个名叫 <code>allowed_dnats</code> 的链中被丢弃。现在我们来查看它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft list chain inet filter allowed_dnats</span></span>
<span class="line"><span>table inet filter {</span></span>
<span class="line"><span> chain allowed_dnats {</span></span>
<span class="line"><span>  meta nfproto ipv4 ip daddr . tcp dport @allow_in accept</span></span>
<span class="line"><span>  drop</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>接受 <code>@allow_in</code> 集的数据包的规则没有显示在跟踪日志中。我们通过列出元素的方式，再次检查上述报文的目标地址是否在 <code>@allow_in</code> 集中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft &quot;get element inet filter allow_in { 192.168.70.10 . 22 }&quot;</span></span>
<span class="line"><span>Error: Could not process rule: No such file or directory</span></span></code></pre></div><p>不出所料，地址-服务对并没有出现在集合中。我们将其添加到集合中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft &quot;add element inet filter allow_in { 192.168.70.10 . 22 }&quot;</span></span></code></pre></div><p>现在运行查询命令，它将返回新添加的元素。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft &quot;get element inet filter allow_in { 192.168.70.10 . 22 }&quot;</span></span>
<span class="line"><span>table inet filter {</span></span>
<span class="line"><span>   set allow_in {</span></span>
<span class="line"><span>      type ipv4_addr . inet_service</span></span>
<span class="line"><span>      elements = { 192.168.70.10 . 22 }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>ssh</code> 命令现在应该可以工作，且跟踪结果可以反映出该变化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 497abf58 inet filter forward rule ct status dnat jump allowed_dnats (verdict jump allowed_dnats)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>trace id 497abf58 inet filter allowed_dnats rule meta nfproto ipv4 ip daddr . tcp dport @allow_in accept (verdict accept)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>trace id 497abf58 ip postrouting packet: iif &quot;enp0&quot; oif &quot;veth21&quot; ether .. trace id 497abf58 ip postrouting policy accept</span></span></code></pre></div><p>这表明报文通过了转发路径中的最后一个钩子 - <code>postrouting</code>。</p><p>如果现在仍然无法连接，问题可能处在报文流程的后续阶段，有可能并不在 nftables 的规则集合范围之内。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>本文介绍了如何通过 nftables 的跟踪机制检查丢包或其他类型的连接问题。本系列的下一篇文章将展示如何检查连接跟踪系统和可能与连接跟踪流相关的 NAT 信息。</p><hr>`,68)),n("p",null,[a[1]||(a[1]=e("via: ",-1)),t(s,{href:"https://fedoramagazine.org/network-address-translation-part-1-packet-tracing/"},{default:i(()=>[...a[0]||(a[0]=[e("https://fedoramagazine.org/network-address-translation-part-1-packet-tracing/",-1)])]),_:1})]),n("p",null,[a[6]||(a[6]=e("作者：",-1)),t(s,{href:"https://fedoramagazine.org/author/strlen/"},{default:i(()=>[...a[2]||(a[2]=[e("Florian Westphal",-1)])]),_:1}),a[7]||(a[7]=e(" 选题：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[e("lujun9972",-1)])]),_:1}),a[8]||(a[8]=e(" 译者：",-1)),t(s,{href:"https://github.com/cooljelly"},{default:i(()=>[...a[4]||(a[4]=[e("cooljelly",-1)])]),_:1}),a[9]||(a[9]=e(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[a[12]||(a[12]=e("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[e("Linux中国",-1)])]),_:1}),a[14]||(a[14]=e(" 荣誉推出",-1))])])}const C=p(c,[["render",h]]);export{v as __pageData,C as default};
